$('logout').onclick=async()=>{try{await LabAPI.logout();}catch{}groups=[];runs=[];selected=null;currentLinkGroup=null;$('admin').hidden=true;$('login').hidden=false;$('groups').replaceChildren();$('runs').replaceChildren();$('runsbox').hidden=true;$('linkbox').hidden=true;$('group-link').value='';$('new-group').textContent='';$('class-link').value='';$('class-linkbox').hidden=true;$('codebox').hidden=true;$('group-code').value='';$('account-panel').hidden=true;$('account-form').reset();$('class-summary').replaceChildren();$('current-email').textContent='';classes=[];currentCodeGroup=null;status('ログアウトしました。');};
$('export').onclick=()=>{if(!selected||!runs.length)return;const lines=[['クラス',selected.label],['実験条件',JSON.stringify(selected.settings)],['保存日時','記録ID','班名','実験温度(℃)','時間(s)','入力体積(mL)','濃度(mol/L)','平均減少速度(mol/(L s))','k(s^-1)','初濃度(mol/L)']];for(const r of runs)r.analysis.concentrations.forEach((p,i)=>lines.push([r.created_at,r.id,r.team_label||'',r.settings?.temp??selected.settings.temp,p.t,r.rows[i].vol,p.c??'',i===0?'':r.analysis.rates[i-1]?.rate??'',r.analysis.k??'',r.analysis.c0??'']));const escape=v=>{let s=String(v);if(/^[=+@\-\t\r\n]/.test(s)&&typeof v==='string')s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\ufeff'+lines.map(r=>r.map(escape).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='教員用_実験記録.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(!LabAPI.ready()){$('login').querySelector('button').disabled=true;status('保存・認証の初期設定がまだ完了していません。SETUP.mdを参照してください。',true);}

function filteredGroups(){const id=$('class-filter').value;return id?groups.filter(g=>g.class_id===id):groups;}
async function loadClasses(){const result=await LabAPI.rpc('lab_admin_classes',{},true);classes=Array.isArray(result)?result:[];for(const [id,defaultLabel]of[['class-filter','すべてのクラス'],['group-class','講座未所属']]){const select=$(id),value=select.value;select.replaceChildren();const first=document.createElement('option');first.value='';first.textContent=defaultLabel;select.append(first);for(const c of classes){const option=document.createElement('option');option.value=c.id;option.textContent=c.label;select.append(option);}select.value=classes.some(c=>c.id===value)?value:'';}}
function showCode(id,label,code){currentCodeGroup=id;$('code-label').textContent=label;$('group-code').value=code;$('codebox').hidden=false;}
function showClassLink(label,token){const u=new URL('./',location.href);u.searchParams.set('v',Date.now().toString(36));u.hash=new URLSearchParams({class:token}).toString();$('class-link-label').textContent=label;$('class-link').value=u.href;$('class-linkbox').hidden=false;}
function teamResults(g){return g.teams?.length?g.teams:g.latest?[g.latest]:[];}
function renderClassSummary(){const box=$('class-summary');box.replaceChildren();const selected=filteredGroups(),count=selected.filter(g=>g.latest).length,p=document.createElement('p');p.className='help';p.textContent=`提出済み ${count} クラス ／ ${selected.length} クラス（班名ごとの最新記録で集約）`;box.append(p);if(!selected.length)return;
const div=document.createElement('div');div.className='scroll';const table=document.createElement('table'),head=document.createElement('tr');['講座','クラス','班名','提出','実験温度(℃)','速度定数 k(s⁻¹)'].forEach(v=>cell(head,v,'th'));table.append(head);const comparison=[];
for(const g of selected){const results=teamResults(g);for(const t of results.length?results:[null]){const row=document.createElement('tr');[g.class_label||'未所属',g.label,t?.team_label|| (t?'旧記録':'—'),t?'提出済み':'未提出',t?.temperature??'—',t?format(t.k):'—'].forEach(v=>cell(row,v));table.append(row);if(t)comparison.push({...g,label:g.label+' / '+(t.team_label||'旧記録'),latest:t});}}
div.append(table);box.append(div);drawClassComparison(box,comparison);}
$('create-class').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const c=await LabAPI.rpc('lab_admin_class_create',{p_label:$('class-label').value.trim()},true);showClassLink(c.label,c.token);await list();$('group-class').value=c.id;$('class-filter').value=c.id;await list();status('講座を作成しました。必要な数のクラスを追加してください。');}catch(error){status(error.message,true);}finally{button.disabled=false;}};
