$('class-link-button').onclick=async()=>{const id=$('class-filter').value;if(!id){status('先に講座を選択してください。',true);return;}if(!confirm('選択講座の共通リンクを再発行しますか？以前の共通リンクは使えなくなります。'))return;try{const c=await LabAPI.rpc('lab_admin_class_link',{p_class_id:id},true);showClassLink(c.label,c.token);status('講座共通リンクを再発行しました。');}catch(e){status(e.message,true);}};
async function copyValue(id){try{await navigator.clipboard.writeText($(id).value);status('コピーしました。');}catch{$(id).select();status('選択した内容を手動でコピーしてください。');}}
$('copy-class-link').onclick=()=>copyValue('class-link');$('copy-code').onclick=()=>copyValue('group-code');
$('class-export').onclick=()=>{const lines=[['講座','クラス','班名','保存日時','実験温度(℃)','時間(s)','濃度(mol/L)','k(s^-1)']];for(const g of filteredGroups()){const results=teamResults(g);if(!results.length)lines.push([g.class_label||'',g.label,'','未提出','','','','']);for(const t of results)for(const point of t.concentrations||[])lines.push([g.class_label||'',g.label,t.team_label||'旧記録',t.created_at,t.temperature,point.t,point.c??'',t.k??'']);}downloadCSV(lines,'講座集約_各班の最新記録.csv');};
function downloadCSV(lines,name){const safe=v=>{let s=String(v??'');if(typeof v==='string'&&(['=','+','@','-'].includes(s[0])||[9,10,13].includes(s.charCodeAt(0))))s="'"+s;return '"'+s.replaceAll('"','""')+'"';},csv=String.fromCharCode(65279)+lines.map(r=>r.map(safe).join(',')).join(String.fromCharCode(13,10)),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('account-toggle').onclick=()=>{$('account-panel').hidden=!$('account-panel').hidden;};
